import React, { useEffect, useState } from "react";
import styled from "styled-components";
import TabBar from "../../components/common/TabBar";
import ProfileHeader from "../../components/common/ProfileHeader";
import TextBox from "../../components/common/TextBox";
import Button from "../../components/common/Button";

/* ---- Styled Wrappers ---- */
const PageWrapper = styled.div`
  background-color: ${({ theme }) => theme.colors.background};
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
`;

const ContentWrapper = styled.div`
  width: 90%;
  max-width: 1200px;
  display: flex;
  flex-direction: column;
  gap: 24px;
  padding: 60px 0;
`;

const Card = styled.div`
  background: #fff;
  border-radius: 16px;
  padding: 32px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
`;

const SectionTitle = styled.h2`
  font-size: 20px;
  font-weight: 700;
  color: #2d2d2d;
  margin-bottom: 20px;
`;

const HeaderRow = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
`;

/* ---- Component ---- */
const ProfilePage: React.FC = () => {
  const [isEditing, setIsEditing] = useState(false);
  const [customer, setCustomer] = useState<any>(null);

  useEffect(() => {
    // Load from localStorage FIRST for instant UI
    const stored = localStorage.getItem("customer");
    if (stored) {
      setCustomer(JSON.parse(stored));
    }

    // Optionally fetch latest profile from backend
    const token = localStorage.getItem("customerToken");
    if (token) {
      fetch("http://localhost:5000/api/customers/me", {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      })
        .then((res) => res.json())
        .then((data) => {
          setCustomer(data);
          localStorage.setItem("customer", JSON.stringify(data));
        })
        .catch(() => {});
    }
  }, []);

  if (!customer)
    return <div style={{ padding: 40 }}>Loading profile...</div>;

  const fullName = customer.firstName + " " + customer.lastName;

  return (
    <PageWrapper>
      <TabBar type="customer" />

      <ContentWrapper>
        {/* ---------- Profile Header ---------- */}
        <ProfileHeader
          type="customer"
          name={fullName}
          stat1={0}                 // bookings count (hook later)
          stat2={0}                 // visited count (hook later)
          stat3={0}                 // loyalty programs count (later)
        />

        {/* ---------- Personal Information ---------- */}
        <Card>
          <HeaderRow>
            <SectionTitle>Personal Information</SectionTitle>
            <Button
              onClick={() => setIsEditing(!isEditing)}
              style={{
                padding: "8px 16px",
                fontSize: "14px",
                borderRadius: "8px",
                width: "auto",
              }}
            >
              {isEditing ? "Save" : "Edit"}
            </Button>
          </HeaderRow>

          <div
            style={{
              display: "grid",
              gridTemplateColumns: "1fr 1fr",
              gap: "16px",
            }}
          >
            <TextBox
              label="Name"
              value={fullName}
              readOnly={!isEditing}
            />

            {/* Removed phone input as requested */}

            <div style={{ gridColumn: "1 / span 2" }}>
              <TextBox
                label="Email"
                value={customer.email}
                readOnly={!isEditing}
                style={{ width: "100%" }}
              />
            </div>
          </div>
        </Card>
      </ContentWrapper>
    </PageWrapper>
  );
};

export default ProfilePage;
